  );

  const ubicaciones = await listarUbicaciones();
  cache.ubicaciones = Object.fromEntries(
    ubicaciones.map(u => [String(u.id), u])
  );

  cargandoCache = false;
}

const getFromCache = (value, cacheObj, formato) => {
  if (value === null || value === undefined) return "";

  if (Array.isArray(value)) {
    return value
      .map((id) => cacheObj[String(id)])
      .filter(Boolean)
      .map(formato)
      .join(", ");
  }

  const item = cacheObj[String(value)];
  return item ? formato(item) : "";
};

