const NOMBRE_COLECCION = "eventos";

let cache = {
  personas: null,
  tractores: null,
  furgones: null,
  proveedores: null,
  ubicaciones: null,
};

let cargandoCache = false;

async function cargarCache() {

  if (cache.personas) return;

  if (cargandoCache) {
    while (cargandoCache) {
      await new Promise(r => setTimeout(r, 50));
    }
    return;
  }

  cargandoCache = true;

  const personas = await listarPersonas();
  cache.personas = Object.fromEntries(
    personas.map(p => [String(p.dni), p])
  );

  const tractores = await listarTractores();
  cache.tractores = Object.fromEntries(
    tractores.map(t => [String(t.id), t])
  );

  const furgones = await listarFurgones();
  cache.furgones = Object.fromEntries(
    furgones.map(f => [String(f.id), f])
  );

  const proveedores = await listarProveedores();
  cache.proveedores = Object.fromEntries(
    proveedores.map(e => [String(e.id), e])
  );

  const ubicaciones = await listarUbicaciones();
  cache.ubicaciones = Object.fromEntries(
    ubicaciones.map(u => [String(u.id), u])
  );

  cargandoCache = false;
}

const getFromCache = (value, cacheObj, formato) => {
  if (value === null || value === undefined) return "";

  if (Array.isArray(value)) {
    return value
      .map((id) => cacheObj[String(id)])
      .filter(Boolean)
      .map(formato)
      .join(", ");
  }

  const item = cacheObj[String(value)];
  return item ? formato(item) : "";
};

function enriquecerEvento(ev) {
  const persona = cache.personas[String(ev.persona)];
  //const tractor = cache.tractores[String(ev.tractor)];
  //const furgon = cache.furgones[String(ev.furgon)];
  const sucursal = cache.ubicaciones[String(ev.sucursal)];
  const personaRelacionada = cache.personas[String(ev.personaRelacionada)];
  //const tractorRelacionado = cache.tractores[String(ev.tractorRelacionado)];

  const furgonIds = Array.isArray(ev.furgon)
    ? ev.furgon.map(String).map((id) => id.trim()).filter(Boolean)
    : ev.furgon === null || ev.furgon === undefined || ev.furgon === ""
      ? []
      : [String(ev.furgon).trim()].filter(Boolean);

  return {
    ...ev,
    furgon: furgonIds,
    cliente: Array.isArray(ev.cliente) ? null : normalizarCliente(ev.cliente),

    nombrePersona: persona
      ? `${persona.apellido}, ${persona.nombres}`
      : "",

    nombreMecanico: getFromCache(ev.mecanico, cache.personas, p => `${p.apellido}, ${p.nombres}`),
    nombreChofer: getFromCache(ev.chofer, cache.personas, p => `${p.apellido}, ${p.nombres}`),

    tractorFull: getFromCache(ev.tractor, cache.tractores, (t) => `${t.id} (${t.dominio})`),
    furgonFull: getFromCache(furgonIds, cache.furgones, (f) => `${f.id} (${f.dominio})`),

    nombreProveedor: getFromCache(ev.proveedor, cache.proveedores, p => `${p.id} - ${p.nombre} (${p.cuit})`),

    nombreSucursal: sucursal
      ? sucursal.nombre
      : "",

    nombrePersonaRelacionada: personaRelacionada
      ? `${personaRelacionada.apellido}, ${personaRelacionada.nombres}`
      : "",


    tractorRelacionadoFull: getFromCache(ev.tractorRelacionado, cache.tractores, (t) => `${t.id} (${t.dominio})`),

  };
}

async function listarEventosPorArea(area, limit = 200, offset = 0) {

  await cargarCache();

  const eventos = await listarColeccion(
    NOMBRE_COLECCION,
    {
      where: ["area", "==", area],
      // Igual que BESS: fecha contiene tanto Timestamp como mapas históricos.
      // Firestore ordena esos tipos por separado; ordenar por fecha excluye recientes.
      orderBy: ["orden", "desc"],
      limit,
      offset
    }
  );


  return eventos.map(enriquecerEvento);
}

