async function agregarEventoLegacy(codigo, data, usuario = "") {
  const documentOperator = operatorContext.getStore()?.creating && isDocument(data);
  const consumoOperator = !documentOperator && operatorContext.getStore()?.creating
    && ['tractores', 'furgones'].includes(data.area) && data.repuestos?.length > 0;
  if (codigo) {
    return agregar(NOMBRE_COLECCION, codigo, {
      ...data,
      fecha: admin.firestore.FieldValue.serverTimestamp(),
      usuario,
    });
  }

  const area = String(data.area || "").trim().toLowerCase();
  if (!area) {
    const error = new Error("El área es obligatoria");
    error.status = 400;
    throw error;
  }

  const { confirmacionVinculo: _ack, ...documentData } = data;
  const datosEvento = documentOperator ? documentData : area === "porteria" && data.formulario === "movPorteria"
    ? {
      ...data,
      furgon: normalizarIds(data.furgon),
      cliente: normalizarCliente(data.cliente),
    }
    : data;

  const iniciaViaje = area === "porteria" && datosEvento.tipo === "SALIDA";
  if (iniciaViaje) {
    const error = new Error("El flujo legacy no puede iniciar viajes; debe usar el flujo transaccional de Portería");
    error.status = 409;
    throw error;
  }
  const datosViaje = iniciaViaje
    ? normalizarDatosViaje({
      area: "trafico",
      tipo: "VIAJE",
      persona: datosEvento.persona,
      tractor: datosEvento.tractor,
      furgon: datosEvento.furgon,
      cliente: datosEvento.cliente,
      cargado: Boolean(datosEvento.cargado),
      detalle: datosEvento.detalle || null,
      formulario: "viaje",
      usuario,
      sucursal: datosEvento.sucursal || null,
    })
    : null;

  return transaccionConRelaciones(db, async (transaction) => {
    const sectores = await transaction.get(db.collection("sectores"));
    const viajesActivos = iniciaViaje
      ? await transaction.get(db.collection("viajes").where("estado", "==", true))
      : null;
    const ultimoEvento = await transaction.get(
      db.collection(NOMBRE_COLECCION)
        .where("area", "==", area)
        .orderBy("orden", "desc")
        .limit(1)
    );
    const sectorDoc = sectores.docs.find(
      (doc) => String(doc.data().nombre || "").trim().toLowerCase() === area
    );
    if (!sectorDoc) {
      const error = new Error(`Sector inválido: ${area}`);
      error.status = 400;
      throw error;
    }

    const ultimoContador = Number(sectorDoc.data().ultimo || 0);
    const ultimoOrden = Number(ultimoEvento.docs[0]?.data().orden || 0);
    const orden = Math.max(ultimoContador, ultimoOrden) + 1;
    const id = `${String(sectorDoc.id).padStart(3, "0")}-${String(orden).padStart(8, "0")}`;
    const eventoRef = db.collection(NOMBRE_COLECCION).doc(id);
    const viajeRef = null;
    const eventoExistente = await transaction.get(eventoRef);

    if (eventoExistente.exists) {
      const error = new Error(`Ya existe el evento ${id}`);
      error.status = 409;
      throw error;
    }

    if (iniciaViaje) {
      const conflicto = buscarConflictoViajeActivo(viajesActivos, datosViaje);
      if (conflicto) {
        const error = new Error(
          `El ${conflicto.campo} ya está asociado al viaje activo ${conflicto.viajeId}`
        );
        error.status = 409;
        throw error;
      }
    }

    const movimientos = documentOperator
      ? data.movimientoStock === 'SIN MOVIMIENTO' ? [] : data.ingresos.map(({ id, cantidad, unidad }) => ({ id, unidad, cantidad: data.movimientoStock === 'BAJA' ? -cantidad : cantidad }))
      : consumoOperator ? data.repuestos.map(item => ({ ...item, cantidad: -item.cantidad })) : [];
    const escribirStock = consumoOperator || (documentOperator && movimientos.length > 0)
      ? await prepararMovimientoStock(transaction, data.deposito, movimientos, { validarUnidades: true }) : null;
    const legacyIdentity = !operatorContext.getStore() && isDocument(data)
      ? await prepareDocumentIdentity(transaction, db, data, id) : null;
    const timestamp = admin.firestore.FieldValue.serverTimestamp();

    transaction.update(sectorDoc.ref, { ultimo: orden });
    transaction.create(eventoRef, {
      ...datosEvento,
      area,
      orden,
      fecha: timestamp,
      usuario,
      ...(consumoOperator ? { movimientos } : {}),
      ...(documentOperator ? { movimientos, modificaciones: [], ingresos: data.ingresos.map(line => ({ ...line, cantidad: data.movimientoStock === 'BAJA' ? -line.cantidad : line.cantidad })) } : {}),
      ...(viajeRef && { viajeId: viajeRef.id }),
    });

    escribirStock?.();
    legacyIdentity?.write(transaction, admin.firestore.Timestamp.now(), 'legacy');

    if (viajeRef) {
      transaction.create(viajeRef, {
        ...datosViaje,
        eventoInicioId: id,
        estado: true,
        fecha: timestamp,
        fechaInicio: timestamp,
      });
    }

    return {
      id,
      ...datosEvento,
      area,
      orden,
      usuario,
      ...(viajeRef && { viajeId: viajeRef.id }),
    };
  });
}

export async function agregarEvento(codigo, data, usuario = "") {
  if (viajesV2Habilitado() && String(data.area ?? "").trim().toLowerCase() === "porteria"
    && ["SALIDA", "ENTRADA"].includes(String(data.tipo ?? "").trim().toUpperCase())) {
    if (codigo) throw Object.assign(new Error("Los IDs de Portería se generan automáticamente"), { status: 400 });
    const resultado = await registrarEventoPorteriaV2(data, usuario);
    if (resultado) return resultado;
    // Una ENTRADA de un único viaje anterior conserva cierre, estadísticas y cálculo legacy.
  }
  const area = String(data.area || "").trim().toLowerCase();
  const tipo = String(data.tipo || "").trim().toUpperCase();
  if (area !== "porteria" || !["SALIDA", "ENTRADA"].includes(tipo)) {
    return agregarEventoLegacy(codigo, data, usuario);
  }
  if (codigo) {
    const error = new Error("Los IDs de movimientos de Portería se generan automáticamente");
    error.status = 400;
    throw error;
  }

  const persona = String(data.persona ?? "").trim();
  if (!persona) {
    const error = new Error("persona es obligatoria para movimientos de Portería");
    error.status = 400;
    throw error;
  }
  const ubicacion = data.ubicacion ?? data.sucursal ?? null;
  const { sucursal: _sucursalHistorica, ...dataSinSucursal } = data;
  const datosEvento = {
    ...dataSinSucursal,
    area,
    tipo,
    persona,
    ubicacion: ubicacion === null || ubicacion === undefined ? null : String(ubicacion).trim(),
    furgon: normalizarIds(data.furgon),
    cliente: normalizarCliente(data.cliente),
  };

  const resultado = await transaccionConRelaciones(db, async (transaction) => {
    const sectores = await transaction.get(db.collection("sectores"));
    const activos = tipo === "SALIDA" ? await buscarViajesActivosPorPersona(transaction, persona) : [];
    const activo = tipo === "SALIDA" ? activos.at(-1) ?? null : await buscarViajeActivoPorPersona(transaction, persona);
    const ultimoEvento = await transaction.get(
      db.collection(NOMBRE_COLECCION).where("area", "==", area).orderBy("orden", "desc").limit(1)
    );
    let ubicacionViaje = datosEvento.ubicacion;
    if (tipo === "SALIDA" && (ubicacionViaje === null || ubicacionViaje === undefined)
      && data.operador !== null && data.operador !== undefined) {
      const operadorId = String(data.operador).trim();
      if (operadorId) {
        const operadorDoc = await transaction.get(db.collection("personas").doc(operadorId));
        if (operadorDoc.exists) {
          const ubicaciones = await transaction.get(db.collection("ubicaciones"));
          ubicacionViaje = resolverUbicacionSalida(
            datosEvento,
            operadorDoc.data(),
            ubicaciones.docs.map((doc) => ({ ...doc.data(), id: doc.id }))
          );
        }
      }
    }
    const datosEventoResuelto = { ...datosEvento, ubicacion: ubicacionViaje };
    const crearViaje = !viajesV2Habilitado() && debeCrearViajeDesdeSalida(tipo, ubicacionViaje);
    const reserva = crearViaje
      ? await reservarIdViaje(transaction, ubicacionViaje)
      : null;
    const sectorDoc = sectores.docs.find(
      (doc) => String(doc.data().nombre || "").trim().toLowerCase() === area
    );
    if (!sectorDoc) {
      const error = new Error(`Sector inválido: ${area}`);
      error.status = 400;
      throw error;
    }

    const cantidadEventos = tipo === "SALIDA" ? activos.length + 1 : 1;
    const ultimoContador = Number(sectorDoc.data().ultimo || 0);
    const ultimoOrden = Number(ultimoEvento.docs[0]?.data().orden || 0);
    const primerOrden = Math.max(ultimoContador, ultimoOrden) + 1;
    const ordenReal = primerOrden + cantidadEventos - 1;
    const crearIdEvento = (orden) =>
      `${String(sectorDoc.id).padStart(3, "0")}-${String(orden).padStart(8, "0")}`;
    const idReal = crearIdEvento(ordenReal);
    const idsAutomaticos = activos.map((_, i) => crearIdEvento(primerOrden + i));
    const idAutomatico = idsAutomaticos.at(-1) ?? null;
    const eventoRealRef = db.collection(NOMBRE_COLECCION).doc(idReal);
    const eventosAutomaticosRefs = idsAutomaticos.map(id => db.collection(NOMBRE_COLECCION).doc(id));
    const existentes = await transaction.getAll(eventoRealRef,
      ...eventosAutomaticosRefs);
    if (existentes.some((snapshot) => snapshot.exists)) {
      const error = new Error("Ya existe uno de los IDs de evento reservados");
      error.status = 409;
      throw error;
    }
    // Preparamos los cierres antes de comenzar las escrituras.
    // Firestore exige realizar todas las lecturas antes de escribir.
    const fechaPrevia = admin.firestore.Timestamp.now();

    const fechasCierrePrevias = activos.map((viaje, i) => {
      const siguiente = activos[i + 1];

      const hasta = siguiente
        ? normalizarFechaInstantanea(
          siguiente.fechaInicio ?? siguiente.fecha
        ).getTime()
        : fechaPrevia.toMillis();

      const inicio = normalizarFechaInstantanea(
        viaje.fechaInicio ?? viaje.fecha
      ).getTime();

      if (
        !Number.isFinite(inicio) ||
        !Number.isFinite(hasta) ||
        hasta - 1000 <= inicio
      ) {
        throw Object.assign(
          new Error(
            "Las fechas de los viajes activos no permiten reconstruir una cadena cronológica"
          ),
          { status: 400 }
        );
      }

      return admin.firestore.Timestamp.fromMillis(hasta - 1000);
    });

    const cierresEstadisticosPrevios = [];

    if (tipo === "SALIDA") {
      for (const [indice, viaje] of activos.entries()) {
        const viajeCerrado = {
          ...viaje,
          estado: false,
          fechaFin: fechasCierrePrevias[indice],
        };

        const contribucion =
          construirContribucionMensual(viajeCerrado);

        if (contribucion) {
          cierresEstadisticosPrevios.push({
            viaje,
            contribucion,
          });
        }
      }
    } else if (tipo === "ENTRADA" && activo) {
      const viajeCerrado = {
        ...activo,
        estado: false,
        fechaFin: fechaPrevia,
      };

      const contribucion =
        construirContribucionMensual(viajeCerrado);

      if (contribucion) {
        cierresEstadisticosPrevios.push({
          viaje: activo,
          contribucion,
        });
      }
    }

    // Un mismo evento puede cerrar varios viajes,
    // incluso pertenecientes a períodos diferentes.
    const periodosEstadisticos = [
      ...new Set(
        cierresEstadisticosPrevios.map(
          ({ contribucion }) => contribucion.periodo
        )
      ),
    ];

    const mensuales = new Map();

    for (const periodo of periodosEstadisticos) {
      const ref = db.collection("mensuales").doc(periodo);
      const snapshot = await transaction.get(ref);

      mensuales.set(periodo, {
        ref,
        snapshot,
      });
    }
    const fecha = fechaPrevia;
    const fechasCierre = fechasCierrePrevias;
    let viajeNuevo = null;
    let cierre = null;
    transaction.update(sectorDoc.ref, { ultimo: ordenReal });

    for (const [indice, anterior] of activos.entries()) {
      const fechaEntradaAutomatica = fechasCierre[indice];
      const entradaAutomatica = {
        area: "porteria",
        tipo: "ENTRADA",
        automatico: true,
        detalle: "Entrada generada automáticamente por sistema",
        persona,
        tractor: planificarMovimientoPorteria({ tipo, viajeActivo: anterior }).tractorEntradaAutomatica,
        furgon: normalizarIds(anterior.furgon),
        cliente: normalizarCliente(anterior.cliente),
        ubicacion: anterior.ubicacion ?? anterior.sucursal ?? datosEventoResuelto.ubicacion,
        orden: primerOrden + indice,
        fecha: fechaEntradaAutomatica,
        usuario,
        viajeId: anterior.id,
      };
      transaction.create(eventosAutomaticosRefs[indice], entradaAutomatica);
      cierre = cerrarViajeEnTransaccion(transaction, anterior,
        { ...entradaAutomatica, id: idsAutomaticos[indice] }, fechaEntradaAutomatica);
      transaction.update(anterior.ref, {
        cierrePorSalidaConsecutiva: true,
        clasificacionFibot: cierre.clasificacionFibot === "NO_CALCULABLE_CORTO"
          ? "NO_CALCULABLE_CORTO" : "NO_CALCULABLE",
        motivoNoCalculable: cierre.clasificacionFibot === "NO_CALCULABLE_CORTO" ? null : "SIN_CIERRE_BASE",
      });
    }

    if (crearViaje) {
      viajeNuevo = crearViajeEnTransaccion(transaction, reserva, {
        persona,
        tractor: datosEventoResuelto.tractor,
        furgon: datosEventoResuelto.furgon,
        cliente: datosEventoResuelto.cliente,
        cargado: Boolean(datosEventoResuelto.cargado),
        detalle: datosEventoResuelto.detalle || null,
        usuario,
      }, idReal, fecha);
    } else if (tipo === "ENTRADA" && activo) {
      cierre = cerrarViajeEnTransaccion(transaction, activo,
        { ...datosEventoResuelto, id: idReal, automatico: false }, fecha);
    }

    const viajeEventoReal = tipo === "SALIDA" ? viajeNuevo : activo;
    transaction.create(eventoRealRef, {
      ...datosEventoResuelto,
      orden: ordenReal,
      fecha,
      usuario,
      ...(viajeEventoReal && { viajeId: viajeEventoReal.id }),
    });

    for (const { viaje, contribucion } of cierresEstadisticosPrevios) {
      const mensual = mensuales.get(contribucion.periodo);

      if (!mensual) continue;

      const datosActuales = mensual.snapshot.exists
        ? mensual.snapshot.data()
        : null;

      // En el primer cierre no existe contribución anterior.
      const nuevosDatos = reemplazarContribucionMensual(
        datosActuales,
        null,
        contribucion,
        fecha
      );

      if (mensual.snapshot.exists) {
        transaction.set(mensual.ref, nuevosDatos);
      } else {
        transaction.create(mensual.ref, nuevosDatos);
      }

      transaction.update(viaje.ref, {
        estadisticasMensualesContribucion: contribucion,
      });

      // Si este mismo evento cerró varios viajes del mismo mes,
      // el siguiente debe partir del resultado recién calculado.
      mensual.snapshot = {
        exists: true,
        data: () => nuevosDatos,
      };
    }

    return {
      id: idReal,
      ...datosEventoResuelto,
      orden: ordenReal,
      usuario,
      viajeId: viajeEventoReal?.id ?? null,
      entradaAutomaticaId: idAutomatico,
      viajeCerradoId: cierre ? activo?.id ?? null : null,
      viajesCerradosIds: tipo === "SALIDA" ? activos.map(viaje => viaje.id) : cierre && activo ? [activo.id] : [],
      entradasAutomaticasIds: idsAutomaticos,
    };
  });

  resultado.recalculosCombustible = [];
  let limiteDiario = false;
  for (const viajeId of resultado.viajesCerradosIds) {
    try {
      const recalculo = await recalcularViajeReconstruido({ viajeId, motivo: "CIERRE_AUTOMATICO", usuario },
        { omitirFibot: limiteDiario });
      resultado.recalculosCombustible.push({ viajeId, ...recalculo });
      if (esLimiteDiario(recalculo)) limiteDiario = true;
    } catch (error) {
      if (esLimiteDiario(error)) limiteDiario = true;
      resultado.recalculosCombustible.push({ estado: "ERROR_POST_CIERRE", viajeId, error: error.message });
    }
  }
  if (resultado.recalculosCombustible.length) resultado.recalculoCombustible = resultado.recalculosCombustible.at(-1);
  if (limiteDiario) resultado.detenidoPor = "LIMITE_DIARIO";
  return resultado;
}

export const modificarEvento = (codigo, data) =>
  modificar(NOMBRE_COLECCION, codigo, {
    ...data,
    ultimaModificacion: admin.firestore.FieldValue.serverTimestamp(),
  });

export const eliminarEvento = (codigo) =>
  eliminar(NOMBRE_COLECCION, codigo);

