import { transaccionConRelaciones } from './transaccion-relaciones.service.js';
import { operatorContext, controlledTransaction } from './operator-write.service.js';
import { RELACIONES } from "./relaciones.service.js";
import { escribirRelacionesEnTransaccion } from "./registro-relaciones.service.js";
import { db } from "../firebase/firebaseAdmin.js";

export async function listarColeccion(coleccion, opciones = {}) {
  try {

    let ref = db.collection(coleccion);
    Object.entries(opciones).forEach(([campo, valor]) => {

      if (["where", "orderBy", "limit", "offset"].includes(campo)) return;

      if (valor !== undefined && valor !== null) {
        ref = ref.where(campo, "==", valor);
      }

    });

    if (opciones.where) {
      const [campo, op, valor] = opciones.where;
      ref = ref.where(campo, op, valor);
    }

    if (opciones.orderBy) {
      const [campo, dir] = opciones.orderBy;
      ref = ref.orderBy(campo, dir);
    }

    if (opciones.limit) {
      ref = ref.limit(opciones.limit);
    }

    if (opciones.offset) {
      ref = ref.offset(opciones.offset);
    }

    const snap = await ref.get();

    return snap.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
    }));

  } catch (error) {

    console.error(
      `[Error] No se pudo listar la colección ${coleccion} desde Firestore.`
    );

    throw error;
  }
}

export async function buscarPorId(coleccion, id) {
  try {
    const idStr = String(id);

    const auxDoc = db.collection(coleccion).doc(idStr);
    const documento = await auxDoc.get();

    if (!documento.exists) return null;

    return { id: documento.id, ...documento.data() };
  } catch (error) {
    console.error(`[Error] No se encontró ${id} en la colección ${coleccion}.`);
    throw error;
  }
}
export async function agregar(coleccion, id, data) {
  try {
    if (!id || typeof id !== "string") {
      throw new Error("El ID debe ser un string válido");
    }

    const ref = db.collection(coleccion).doc(id);
    const finalRelations = !!operatorContext.getStore();
    const transact = finalRelations ? transaccionConRelaciones : controlledTransaction;
    await transact(db, async (transaction) => {
      const existente = await transaction.get(ref);
      if (existente.exists) {
        const error = new Error("Ya existe un documento con ese ID");
        error.status = 409;
        throw error;
      }
      let datos = data;
      if (RELACIONES[coleccion] && !finalRelations) {
        const manifiesto = await transaction.get(db.collection('relacionesIndice').doc(`${coleccion}__${id}`));
        const fechaRelacion = escribirRelacionesEnTransaccion(transaction, coleccion, id, data, manifiesto);
        datos = { ...data, relacionEstablecida: true, fechaRelacion };
      }
      transaction.create(ref, datos);
      return { id, ...data };
    });

    return { id, ...data };

  } catch (error) {
    console.error(`[Error] No se pudo agregar nuevo item a la colección ${coleccion} (${id})`);
    throw error;
  }
}
export async function modificar(coleccion, id, data) {
  try {
    const aux = db.collection(coleccion).doc(id);
    const finalRelations = !!operatorContext.getStore();
    const transact = finalRelations ? transaccionConRelaciones : controlledTransaction;
    const actualizado = await transact(db, async tx => {
      const snap = await tx.get(aux);
      if (!snap.exists) return false;
      let datos = data;
