export const RELACIONES = Object.freeze({
  eventos: {personas:['persona','chofer','mecanico'],tractores:['tractor','tractores'],furgones:['furgon','furgones'],vehiculos:['vehiculo','vehiculos'],proveedores:['proveedor','proveedores'],empresas:['cliente','clientes'],stock:['ingresos','repuestos','herramientas']},
  asignaciones: {personas:['persona'],stock:['herramientas','ingresos']},
  movimientos: {personas:['persona','chofer'],tractores:['tractor','tractores'],vehiculos:['vehiculo','vehiculos']},
  viajes: {personas:['persona','chofer','mecanico'],tractores:['tractor','tractores'],furgones:['furgon','furgones'],empresas:['cliente','clientes']}
});
const normalizar = value => {
  if (value === null || value === undefined || value === '') return [];
  if (Array.isArray(value)) return value.flatMap(normalizar);
  if (typeof value === 'object') {
    if (value.id !== undefined) return normalizar(value.id);
    return []; // no interpretar mapas arbitrarios como IDs
  }
  if (typeof value !== 'string' && typeof value !== 'number') return [];
  const id = String(value).trim();
  return id ? [id] : [];
};
export function extraerRelaciones(coleccion, documento) {
  const esquema = RELACIONES[coleccion];
  if (!esquema || !documento) return [];
  const result = new Map();
  for (const [destino, campos] of Object.entries(esquema)) {
    for (const campo of campos) {
      for (const id of normalizar(documento[campo])) {
        const clave = `${destino}/${id}`;
        if (!result.has(clave)) result.set(clave, {coleccion:destino,id,campos:[]});
        const relacion = result.get(clave);
        if (!relacion.campos.includes(campo)) relacion.campos.push(campo);
      }
    }
  }
  return [...result.values()];
}
export function compararRelaciones(coleccion, anterior, siguiente) {
  const prev = new Map(extraerRelaciones(coleccion,anterior).map(x=>[`${x.coleccion}/${x.id}`,x]));
  const next = new Map(extraerRelaciones(coleccion,siguiente).map(x=>[`${x.coleccion}/${x.id}`,x]));
  return {agregar:[...next].filter(([k])=>!prev.has(k)).map(([,v])=>v),quitar:[...prev].filter(([k])=>!next.has(k)).map(([,v])=>v),mantener:[...next].filter(([k])=>prev.has(k)).map(([,v])=>v)};
}

