function actualizarStockDeposito(stock = [], movimientos, multiplicador = 1) {
    const resultado = stock.map((item) => ({ ...item }));
    for (const movimiento of movimientos) {
        const item = resultado.find((actual) => String(actual.id) === movimiento.id);
        const delta = movimiento.cantidad * multiplicador;
        if (!item && delta < 0) {
            const error = new Error(`El artículo ${movimiento.id} no existe en el depósito`);
            error.status = 409;
            throw error;
        }
        if (item) {
            const cantidad = Number(item.cantidad || 0) + delta;
            if (cantidad < 0) {
                const error = new Error(`Stock insuficiente para ${movimiento.id}`);
                error.status = 409;
                throw error;
            }
            item.cantidad = cantidad;
        } else {
            resultado.push({ id: movimiento.id, cantidad: delta, unidad: movimiento.unidad });
        }
    }
    return resultado.map(({ id, cantidad, unidad }) => ({ id, cantidad, unidad }));
}

