export async function prepararMovimientoStock(transaction, depositoId, movimientos, { validarUnidades = false } = {}) {
    const items = validarMovimientos(movimientos);
    if (!depositoId) throw Object.assign(new Error('El depósito es obligatorio'), { status: 400 });
    const depositoRef = db.collection('depositos').doc(String(depositoId));
    const [deposito, ...articulos] = await Promise.all([
        transaction.get(depositoRef),
        ...items.map(item => transaction.get(db.collection(NOMBRE_COLECCION).doc(item.id))),
    ]);
    if (!deposito.exists || articulos.some(articulo => !articulo.exists)) {
        throw Object.assign(new Error('Depósito o artículo inexistente'), { status: 404 });
    }
    if (validarUnidades) {
        const rows = deposito.data().stock;
        if (!Array.isArray(rows) || rows.some(row => !row || typeof row !== 'object') || new Set(rows.map(row => String(row.id))).size !== rows.length) {
            throw Object.assign(new Error('El depósito tiene existencias inconsistentes; requiere revisión'), { status: 409 });
        }
    }
    const cantidades = articulos.map((articulo, index) => {
        if (validarUnidades) {
            const item = items[index];
            const entrada = (deposito.data().stock || []).find(row => String(row.id) === item.id);
            if (articulo.data().unidad !== item.unidad || (entrada && entrada.unidad !== item.unidad)) {
                throw Object.assign(new Error(`Unidad incompatible para ${item.id}`), { status: 422 });
            }
            const validBalance = value => (typeof value === 'number' || (typeof value === 'string' && value.trim() !== '')) && Number.isFinite(Number(value));
            if (!validBalance(articulo.data().cantidad) || (entrada && !validBalance(entrada.cantidad))) {
                throw Object.assign(new Error(`Existencias inválidas para ${item.id}`), { status: 409 });
            }
        }
        const cantidad = Number(articulo.data().cantidad || 0) + items[index].cantidad;
        if (cantidad < 0) throw Object.assign(new Error(`Stock insuficiente para ${items[index].id}`), { status: 409 });
        return cantidad;
    });
    const stock = actualizarStockDeposito(deposito.data().stock, items);
    return () => {
        articulos.forEach((articulo, index) => transaction.update(articulo.ref, { cantidad: cantidades[index] }));
        transaction.update(depositoRef, { stock });
    };
}

export async function registrarMovimientoStock({ depositoId, movimientos, evento }, usuario) {
    const items = validarMovimientos(movimientos);
    if (!depositoId) {
        const error = new Error("El depósito es obligatorio");
        error.status = 400;
        throw error;
    }

    return transaccionConRelaciones(db, async (transaction) => {
        const escribirStock = await prepararMovimientoStock(transaction, depositoId, items);
        const eventoPreparado = await prepararEvento(transaction, evento || {}, usuario);
        escribirStock();
        transaction.update(eventoPreparado.sector.ref, { ultimo: eventoPreparado.orden });
        transaction.create(db.collection("eventos").doc(eventoPreparado.id), {
            ...(evento || {}),
            area: eventoPreparado.area,
            tipo: evento?.tipo || "STOCK",
            deposito: String(depositoId),
            movimientos: items,
            orden: eventoPreparado.orden,
            usuario,
            fecha: admin.firestore.FieldValue.serverTimestamp(),
        });
        return { id: eventoPreparado.id, movimientos: items.length };
    });
}

export async function transferirStockDepositos({ origenId, destinoId, movimientos, evento }, usuario) {
    const items = validarMovimientos(movimientos).map((item) => ({
        ...item,
        cantidad: Math.abs(item.cantidad),
    }));
    if (!origenId || !destinoId || String(origenId) === String(destinoId)) {
        const error = new Error("Los depósitos de origen y destino deben ser diferentes");
        error.status = 400;
        throw error;
    }

    return transaccionConRelaciones(db, async (transaction) => {
        const origenRef = db.collection("depositos").doc(String(origenId));
        const destinoRef = db.collection("depositos").doc(String(destinoId));
        const [origen, destino] = await Promise.all([
            transaction.get(origenRef),
            transaction.get(destinoRef),
        ]);
        const eventoPreparado = await prepararEvento(transaction, evento || {}, usuario);
        if (!origen.exists || !destino.exists) {
            const error = new Error("Depósito inexistente");
            error.status = 404;
            throw error;
        }

        transaction.update(origenRef, {
            stock: actualizarStockDeposito(origen.data().stock, items, -1),
        });
        transaction.update(destinoRef, {
            stock: actualizarStockDeposito(destino.data().stock, items),
        });
        transaction.update(eventoPreparado.sector.ref, { ultimo: eventoPreparado.orden });
        transaction.create(db.collection("eventos").doc(eventoPreparado.id), {
            ...(evento || {}),
            area: eventoPreparado.area,
            tipo: evento?.tipo || "MOVIMIENTO INTERNO",
            origen: String(origenId),
            destino: String(destinoId),
            movimientos: items,
            orden: eventoPreparado.orden,
            usuario,
            fecha: admin.firestore.FieldValue.serverTimestamp(),
        });
        return { id: eventoPreparado.id, movimientos: items.length };
    });
}


