}

export async function transferirStockDepositos({ origenId, destinoId, movimientos, evento }, usuario) {
    const items = validarMovimientos(movimientos).map((item) => ({
        ...item,
        cantidad: Math.abs(item.cantidad),
    }));
    if (!origenId || !destinoId || String(origenId) === String(destinoId)) {
        const error = new Error("Los depósitos de origen y destino deben ser diferentes");
        error.status = 400;
        throw error;
    }

    return transaccionConRelaciones(db, async (transaction) => {
        const origenRef = db.collection("depositos").doc(String(origenId));
        const destinoRef = db.collection("depositos").doc(String(destinoId));
        const [origen, destino] = await Promise.all([
            transaction.get(origenRef),
            transaction.get(destinoRef),
        ]);
        const eventoPreparado = await prepararEvento(transaction, evento || {}, usuario);
        if (!origen.exists || !destino.exists) {
            const error = new Error("Depósito inexistente");
            error.status = 404;
            throw error;
        }

        transaction.update(origenRef, {
            stock: actualizarStockDeposito(origen.data().stock, items, -1),
        });
        transaction.update(destinoRef, {
            stock: actualizarStockDeposito(destino.data().stock, items),
        });
        transaction.update(eventoPreparado.sector.ref, { ultimo: eventoPreparado.orden });
        transaction.create(db.collection("eventos").doc(eventoPreparado.id), {
            ...(evento || {}),
            area: eventoPreparado.area,
            tipo: evento?.tipo || "MOVIMIENTO INTERNO",
            origen: String(origenId),
            destino: String(destinoId),
            movimientos: items,
            orden: eventoPreparado.orden,
            usuario,
            fecha: admin.firestore.FieldValue.serverTimestamp(),
        });
        return { id: eventoPreparado.id, movimientos: items.length };
    });
}


// Read-only relationships, including historical STOCK event formats.
function stockEntries(value, articuloId) {
    if (!Array.isArray(value)) return [];
    return value.filter(item => {
        if (typeof item === "string" || typeof item === "number") return String(item) === articuloId;
        return item && typeof item === "object" && [item.id, item.stockId, item.articuloId, item.repuestoId, item.codigo].some(v => v != null && String(v) === articuloId);
    });
}
function fechaISO(value) {
    if (!value) return null;
    if (typeof value.toDate === "function") return value.toDate().toISOString();
    if (typeof value === "string") return value;
    if (typeof value === "number") return new Date(value).toISOString();
    if (typeof value.seconds === "number") return new Date(value.seconds * 1000).toISOString();
    return null;
}
export async function obtenerRelacionesArticulo(id, areaUsuario = "") {
    const articuloId = String(id || "").trim();
    if (!articuloId) { const e = new Error("ID obligatorio"); e.status = 400; throw e; }
    const articulo = await db.collection("stock").doc(articuloId).get();
    if (!articulo.exists) { const e = new Error("Artículo inexistente"); e.status = 404; throw e; }
    const [depositos, eventos] = await Promise.all([
        db.collection("depositos").get(),
        db.collection("eventos").select("documentoVersion", "movimientoStock", "remito", "factura", "movimientos", "ingresos", "egresos", "repuestos", "fecha", "tipo", "formulario", "modificaciones", "deposito", "origen", "destino", "usuario", "area", "persona", "tractor", "furgon", "mecanico", "detalle").get(),
    ]);
    const existencias = depositos.docs.flatMap(doc => stockEntries(doc.data().stock, articuloId)
        .map(item => ({ depositoId: doc.id, deposito: doc.data().nombre || doc.data().descripcion || doc.id,
            cantidad: Number(item.cantidad || 0), unidad: item.unidad || articulo.data().unidad || "" })));
    const movimientos = [];
    const documentos = [];
    const trabajos = [];
    const area = String(areaUsuario || "").trim().toLowerCase();
    for (const doc of eventos.docs) {
        const data = doc.data();
        const fecha = fechaISO(data.fecha);
        const tipo = String(data.tipo || '').trim().toUpperCase();
        const taller = ['tractores', 'furgones'].includes(data.area) && ['SERVICE', 'CAMBIO', 'REPARACION', 'REVISION'].includes(tipo);
        const transferencia = !!data.origen && !!data.destino;
        // movimientos is the committed ledger. repuestos only describes work;
        // never infer a stock change from historical repuestos alone.
        const documento = ['REMITO', 'FACTURA'].includes(tipo);
        if (documento && stockEntries(data.ingresos, articuloId).length) documentos.push({ id: doc.id, tipo, numero: data[tipo === 'REMITO' ? 'remito' : 'factura'], fecha, movimiento: data.movimientoStock || 'Movimiento no declarado', impactoConfirmado: data.documentoVersion === 1 });
        const stockEvent = tipo === 'STOCK' || transferencia || taller || /AJUSTE/.test(tipo) || (documento && data.documentoVersion === 1 && ['ALTA', 'BAJA'].includes(data.movimientoStock));
        const fuentes = stockEvent && Array.isArray(data.movimientos) && data.movimientos.length
            ? [{ campo: 'movimientos', items: data.movimientos }]
            : tipo === 'STOCK' ? [{ campo: 'ingresos', items: data.ingresos }, { campo: 'egresos', items: data.egresos }] : [];
        for (const fuente of fuentes) for (const item of stockEntries(fuente.items, articuloId)) {
            const raw = typeof item === 'object' ? Number(item.cantidad) : NaN;
            if (!Number.isFinite(raw) || raw === 0) continue;
            const cantidad = fuente.campo === 'egresos' ? -Math.abs(raw) : raw;
            const operacion = transferencia ? 'transferencia' : documento ? 'movimientoDocumento' : taller ? 'consumoTaller' :
                /AJUSTE/.test(tipo) || /ajuste/i.test(data.formulario || '') ? 'ajuste' : cantidad < 0 ? 'egreso' : 'ingreso';
            movimientos.push({ id: doc.id, fecha, tipo: data.tipo, operacion,
                cantidad, impactoGlobal: transferencia ? 0 : cantidad, unidad: item?.unidad || articulo.data().unidad || '',
                deposito: data.deposito || null, origen: data.origen || null, destino: data.destino || null,
                usuario: data.usuario || null, persona: data.persona || null, area: data.area || null });
        }
        if (area && String(data.area || "").trim().toLowerCase() === area && stockEntries(data.repuestos, articuloId).length) {
            trabajos.push({ id: doc.id, fecha, tipo: data.tipo || "", area: data.area,
                persona: data.persona || null, mecanico: data.mecanico || null,
                tractor: data.tractor || null, furgon: data.furgon || null,
                detalle: data.detalle || null,
                repuestos: stockEntries(data.repuestos, articuloId).map(r => ({ id: articuloId, cantidad: typeof r === "object" ? r.cantidad ?? null : null })) });
        }
    }
    const ordenar = (a, b) => String(b.fecha || "").localeCompare(String(a.fecha || ""));
    movimientos.sort(ordenar);
    trabajos.sort(ordenar);
    return { id: articuloId, existencias, movimientos, documentos, trabajos: trabajos.slice(0, 5) };
}

